CREATE TABLE t1(a,b,c,d); INSERT INTO t1 VALUES('A','C',1,0.1),('A','D',2,0.2),('A','E',3,0.3),('A','C',4,0.4),('B','D',5,0.5),('B','E',6,0.6),('B','C',7,0.7),('B','D',8,0.8),('C','E',9,0.9),('C','C',10,1.0),('C','D',11,1.1),('C','E',12,1.2); CREATE INDEX i1 ON t1(a); CREATE INDEX i2 ON t1(b); CREATE VIEW v1 AS SELECT a,c,max(c) OVER (PARTITION BY a) FROM t1; CREATE VIEW v2 AS SELECT a,c,max(c) OVER (PARTITION BY a),row_number() OVER () FROM t1; CREATE VIEW v3 AS SELECT b,d,max(d) OVER (PARTITION BY b),row_number() OVER (PARTITION BY b) FROM t1; CREATE TABLE t2(x,y,z); INSERT INTO t2 VALUES('W',3,1),('W',2,2),('X',1,4),('X',5,7),('Y',1,9),('Y',4,2),('Z',3,3),('Z',3,4);